import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import LoadingSpinner from '../common/LoadingSpinner';
import { validateLoginForm, getErrorMessage } from '../../utils/helpers';
import { SUCCESS_MESSAGES } from '../../utils/constants';

const Login = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [showResendVerification, setShowResendVerification] = useState(false);

  const { login, isAuthenticated, hasRole } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated()) {
      const from = location.state?.from?.pathname || (hasRole('ROLE_ADMIN') ? '/admin-dashboard' : hasRole('ROLE_VENDOR') ? '/vendor-dashboard' : '/');
      navigate(from, { replace: true });
    }
  }, [isAuthenticated, hasRole, navigate, location]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validateLoginForm(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    setLoading(true);
    setMessage('');
    setErrors({});
    setShowResendVerification(false);

    try {
      await login(formData);
      setMessage(SUCCESS_MESSAGES.LOGIN_SUCCESS);
    } catch (error) {
      const errorMessage = getErrorMessage(error);
      if (error.response?.status === 401 && errorMessage.includes('disabled')) {
        setErrors({ general: 'Account not verified. Please check your email for verification link.' });
        setShowResendVerification(true);
      } else {
        setErrors({ general: errorMessage });
      }
    } finally {
      setLoading(false);
    }
  };

  // Optional: Implement resend if backend supports
  const handleResendVerification = () => {
    alert('Resend verification email functionality can be added if backend supports it.');
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="auth-header">
          <h2>Login to FoodTruck Hub</h2>
          <p>Access your vendor dashboard or admin panel</p>
        </div>

        {message && <div className="success-message">{message}</div>}
        {errors.general && <div className="error-message">{errors.general}</div>}
        {showResendVerification && <button onClick={handleResendVerification} className="btn btn-outline">Resend Verification Email</button>}

        <form onSubmit={handleSubmit} className="auth-form">
          {/* form fields remain the same */}
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input type="text" id="username" name="username" value={formData.username} onChange={handleChange} className={errors.username ? 'error' : ''} placeholder="Enter your username" />
            {errors.username && <span className="error-text">{errors.username}</span>}
          </div>

          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input type="password" id="password" name="password" value={formData.password} onChange={handleChange} className={errors.password ? 'error' : ''} placeholder="Enter your password" />
            {errors.password && <span className="error-text">{errors.password}</span>}
          </div>

          <button type="submit" className="auth-button" disabled={loading}>
            {loading ? 'Signing In...' : 'Sign In'}
          </button>
        </form>

        <div className="auth-footer">
          <p>Don't have an account? <Link to="/register">Register here</Link></p>
        </div>
      </div>
    </div>
  );
};

export default Login;
